class Solution:
    def candy(self, ratings: List[int]) -> int:
        n = len(ratings)
        c = [1] * n

        for i in range(1, n):
            if ratings[i] > ratings[i - 1]:
                c[i] = c[i - 1] + 1
        for i in range(n - 2, -1, -1):
            if ratings[i] > ratings[i + 1] and c[i] <= c[i + 1]:
                c[i] = c[i + 1] + 1

        return sum(c)

impl Solution {
  pub fn candy(ratings: Vec<i32>) -> i32 {
    let n = ratings.len();
    let mut c = vec![1i32; n];

    for i in 1..n {
      if ratings[i] > ratings[i - 1] {
        c[i] = c[i - 1] + 1;
      }
    }
    for i in (0..n - 1).rev() {
      if ratings[i] > ratings[i + 1] && c[i] <= c[i + 1] {
        c[i] = c[i + 1] + 1;
      }
    }

    c.iter().sum()
  }
}

const candy = (ratings: number[]): number => {
  const n = ratings.length;
  const c: number[] = new Array(n).fill(1);

  for (let i = 1; i < n; i++) {
    if (ratings[i] > ratings[i - 1]) {
      c[i] = c[i - 1] + 1;
    }
  }
  for (let i = n - 2; i >= 0; i--) {
    if (ratings[i] > ratings[i + 1] && c[i] <= c[i + 1]) {
      c[i] = c[i + 1] + 1;
    }
  }

  return c.reduce((acc, v) => acc + v, 0);
};
